const places = {
 charles:{name:'Charles Bridge',category:'THE STARTING MOMENT',photo:'prague',coords:[50.0865,14.4114],time:'20–30 min',access:'Before the ride',description:'A quiet morning on Prague’s iconic bridge is a lovely way to begin. Take in the Vltava and the castle skyline.',detail:'Walk your bicycle in crowded pedestrian areas. This is a sightseeing stop before leaving Prague; your confirmed cycling start may be elsewhere.',url:'https://prague.eu/en/objevujte/charles-bridge-karluv-most/'},
 melnik:{name:'Mělník Castle & river view',category:'CASTLE & VINEYARDS',photo:'melnik',coords:[50.3516,14.4744],time:'45–60 min',access:'Uphill walk into town',description:'End the day above the meeting of the Vltava and Elbe, with castle views and a wander through the old town.',detail:'The hilltop is a climb from the river path. Leave time for the viewpoint even if you skip the castle interior. Check the official site for September visiting hours.',url:'https://www.lobkowicz-melnik.cz/'},
 terezin:{name:'Terezín Memorial',category:'HISTORY & REMEMBRANCE',photo:'terezin',coords:[50.5138,14.1666],time:'90–120+ min',access:'Optional detour',description:'Make time for a thoughtful visit to the memorial and learn about the victims of Nazi persecution.',detail:'This is a place of remembrance. The Small Fortress and Ghetto Museum are separate locations; the marker indicates the Small Fortress. Choose your visit in advance and allow sufficient time. Detour distance is additional to the stage estimate.',url:'https://www.pamatnik-terezin.cz/'},
 litomerice:{name:'Litoměřice old town',category:'COLOURFUL TOWN SQUARE',photo:'litomerice',coords:[50.5337,14.1314],time:'30–45 min',access:'Short walk from the river',description:'Pastel façades, Renaissance arcades and a beautiful central square make an inviting end-of-day stroll.',detail:'Head to Mírové náměstí and take a relaxed walk around the historic centre. The photograph shows the Old Town Hall in the square. A pleasant place to regroup after the ride.',url:'https://www.litomerice.cz/'},
 strekov:{name:'Střekov Castle',category:'ABOVE THE ELBE',photo:'strekov',coords:[50.6391,14.0508],time:'45–60 min',access:'Optional uphill detour',description:'A ruined castle above Ústí nad Labem offers a dramatic setting overlooking the river valley.',detail:'Visiting the castle requires leaving the riverside route and climbing uphill. You can instead enjoy the view of the castle from below. Confirm opening days before planning an interior visit.',url:'https://www.hrad-strekov.cz/'},
 decin:{name:'Děčín Castle',category:'RIVERSIDE LANDMARK',photo:'decin',coords:[50.7732,14.2122],time:'45–60 min',access:'Uphill approach',description:'A castle perched over the Elbe welcomes you to Děčín, the gateway to the sandstone country.',detail:'Walk up to the castle grounds after the ride. Interior tours and garden access may have separate tickets and opening hours; check the official visitor information.',url:'https://www.zamekdecin.cz/'},
 promenade:{name:'Bad Schandau riverfront',category:'WELCOME TO GERMANY',photo:'schandau',coords:[50.9177,14.1534],time:'30–45 min',access:'At the stage finish',description:'Enjoy the riverside promenade and the little spa town after crossing into Germany through the Elbe valley.',detail:'A shorter riding day leaves room for a relaxed afternoon. The photograph is a view of Bad Schandau from its historic lift. River crossings depend on your operator’s chosen bank and ferry services.',url:'https://bad-schandau.de/'},
 lift:{name:'Historic passenger lift',category:'A DIFFERENT PERSPECTIVE',photo:'schandau',coords:[50.9172,14.1613],time:'30–45 min',access:'Optional visit on foot',description:'Trade the saddle for a viewpoint above Bad Schandau and look back over the river and rooftops.',detail:'The photograph was taken from the historic lift viewpoint. Check seasonal operating hours and ticket information locally. Keep the afternoon flexible if the lift is closed.',url:'https://bad-schandau.de/'},
 bastei:{name:'Bastei Bridge',category:'THE SCENIC SIDE TRIP',photo:'bastei',coords:[50.9618,14.0732],time:'90–150+ min',access:'Optional ferry + steep walk',description:'Sandstone towers and a stone bridge make this an unforgettable optional excursion from the river valley.',detail:'Bastei is high above the river, not on the flat cycle path. From the Rathen area this may involve a ferry and a steep walking route with steps. Park bicycles appropriately. Add extra time and any ferry crossing; skip the detour for an easier final day.',url:'https://www.saechsische-schweiz.de/en/'},
 dresden:{name:'Dresden old town',category:'THE GRAND FINALE',photo:'dresden',coords:[51.0519,13.7416],time:'60–90+ min',access:'At the stage finish',description:'Celebrate the finish with the Elbe skyline, the Frauenkirche and a stroll through Dresden’s historic heart.',detail:'Leave time after arrival for the Frauenkirche, Brühl’s Terrace and the Zwinger courtyards. The photograph shows the skyline from across the river. Museums and interiors have their own visiting hours.',url:'https://www.dresden.de/en/tourism/tourism.php'}
};
